use crate::crypt::session::SessionKey;use sha1::{Digest,Sha1};#[derive(Debug)]struct Rc4{state:[u8;256],i:u8,j:u8}impl Rc4{fn new(key:&[u8])->Self{let mut s=[0u8;256];for(i,b)in s.iter_mut().enumerate(){*b=i as u8}let mut j=0u8;for i in 0..256{j=j.wrapping_add(s[i]).wrapping_add(key[i%key.len()]);s.swap(i,j as usize)}Self{state:s,i:0,j:0}}fn apply(&mut self,d:&mut[u8]){for b in d{self.i=self.i.wrapping_add(1);self.j=self.j.wrapping_add(self.state[self.i as usize]);self.state.swap(self.i as usize,self.j as usize);let k=self.state[self.i as usize].wrapping_add(self.state[self.j as usize]);*b^=self.state[k as usize]}}}fn sha(parts:&[&[u8]])->[u8;20]{let mut h=Sha1::new();for p in parts{h.update(p)}h.finalize().into()}fn keys(k:&SessionKey)->([u8;16],[u8;16]){let h=k.len()/2;let a=sha(&[&k[..h]]);let b=sha(&[&k[h..]]);let mut x=sha(&[&a,&[0u8;20],&b]);let mut g=[0u8;32];g[..20].copy_from_slice(&x);x=sha(&[&a,&x,&b]);g[20..].copy_from_slice(&x[..12]);let mut i=[0;16];let mut o=[0;16];i.copy_from_slice(&g[..16]);o.copy_from_slice(&g[16..]);(i,o)}pub struct WardenBridge{ui:Rc4,uo:Rc4,di:Rc4,do_:Rc4,session_phase:bool}impl WardenBridge{pub fn new(up:&SessionKey,down:&SessionKey)->Self{let(ui,uo)=keys(up);let(di,do_)=keys(down);Self{ui:Rc4::new(&ui),uo:Rc4::new(&uo),di:Rc4::new(&di),do_:Rc4::new(&do_),session_phase:true}}pub fn server_to_client(&mut self,b:&mut[u8]){if self.session_phase{self.uo.apply(b);self.do_.apply(b)}}pub fn client_to_server(&mut self,b:&mut[u8]){if self.session_phase{self.di.apply(b);let done=b.first()==Some(&4);self.ui.apply(b);if done{self.session_phase=false}}}}
